INSERT INTO schema_problem.problem OVERRIDING SYSTEM VALUE VALUES (135, 'Count and Say', 'Run-length encoding (RLE) is a string compression method that works by replacing consecutive identical characters (repeated 2 or more times) with the concatenation of the character and the number marking the count of the characters (length of the run). For example, to compress the string "3322251" we replace "33" with "23", replace "222" with "32", replace "5" with "15" and replace "1" with "11". Thus the compressed string becomes "23321511".', 'MEDIUM', 38.00, 335, 'PUBLIC', '2025-03-19 07:52:22.302749', 22, NULL, NULL, true, 'count-and-say');
