INSERT INTO schema_problem.problem_submission OVERRIDING SYSTEM VALUE VALUES (331, 1, 112, '
public static int canCompleteCircuit(int[] gas, int[] cost) {
  int len = gas.length;
  int[] diff = new int[len];
  int to = 0;
  for(int i = 0; i < len; i++) {
    diff[i] += (gas[i] - cost[i]);
    to += diff[i];
  }
  if(to < 0) {
    return -1;
  }
  int index = 0;
  to = 0;
  for(int i = 0; i < len; i++) {
    to += diff[i];
    if(to < 0) {
      index = i + 1;
      to = 0;
    }
  }
  return index;
}
', 1, NULL, 8.91, 9, '2025-04-28 12:34:11.573988', true, NULL, NULL, 100, 'SUCCESS');
