INSERT INTO schema_problem.solution_code VALUES (206, 126, 1, '
    public static char firstNonRepeatingCharacter(String s) {
        Map<Character, Integer> countMap = new HashMap<>();
        for (char c : s.toCharArray()) {
            countMap.put(c, countMap.getOrDefault(c, 0) + 1);
        }
        for (char c : s.toCharArray()) {
            if (countMap.get(c) == 1)
                return c;
        }
        return ''_'';
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (206, 126, 2, '
char firstNonRepeatingCharacter(char s[]) {
    int count[256] = {0};
    for (int i = 0; s[i] != ''\0''; i++) count[(int)s[i]]++;
    for (int i = 0; s[i] != ''\0''; i++) {
        if (count[(int)s[i]] == 1) return s[i];
    }
    return ''_'';
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (207, 127, 1, '
public static boolean isValid(String s) {
    Stack<Character> stack = new Stack<>();
    for (char c : s.toCharArray()) {
        if (c == ''('' || c == ''{'' || c == ''['') {
            stack.push(c);
        } else {
            if (stack.isEmpty()) return false;
            char top = stack.pop();
            if ((c == '')'' && top != ''('') ||
                (c == ''}'' && top != ''{'') ||
                (c == '']'' && top != ''['')) {
                return false;
            }
        }
    }
    return stack.isEmpty();
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (207, 127, 2, '
int isValid(char* s) {
    char stack[10000];
    int top = -1;
    for (int i = 0; s[i] != ''\0''; i++) {
        char c = s[i];
        if (c == ''('' || c == ''{'' || c == ''['') {
            stack[++top] = c;
        } else {
            if (top == -1) return 0;
            char topChar = stack[top--];
            if ((c == '')'' && topChar != ''('') ||
                (c == ''}'' && topChar != ''{'') ||
                (c == '']'' && topChar != ''['')) {
                return 0;
            }
        }
    }
    return top == -1;
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (208, 128, 1, '
public static int lengthOfLongestSubstring(String s) {
    Set<Character> set = new HashSet<>();
    int left = 0, maxLength = 0;
    for (int right = 0; right < s.length(); right++) {
        while (set.contains(s.charAt(right))) {
            set.remove(s.charAt(left++));
        }
        set.add(s.charAt(right));
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (208, 128, 2, '
    int lengthOfLongestSubstring(char* s) {
        int charIndex[128] = {0}; 
        int maxLength = 0, left = 0;

        for (int right = 0; s[right] != ''\0''; right++) {
            if (charIndex[s[right]] > left) {
                left = charIndex[s[right]];
            }
            charIndex[s[right]] = right + 1;
            int currentLength = right - left + 1;
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
        }
        return maxLength;
    }', NULL);
