    public static boolean isArmstrong(int n) {
        int sum = 0, temp = n, d = String.valueOf(n).length();
        while (temp > 0) {
            sum += Math.pow(temp % 10, d);
            temp /= 10;
        }
        return sum == n;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (219, 140, 2, '
    bool isArmstrong(int n) {
        int d = 0, temp = n, sum = 0; 
        for (int t = n; t > 0; t /= 10, d++); 
        for (temp = n; temp > 0; temp /= 10) { 
            int digit = temp % 10, power = 1; 
            for (int i = 0; i < d; i++) power *= digit; 
            sum += power;
        } 
        return sum == n;
    }', NULL);
