INSERT INTO schema_problem.solution_code VALUES (192, 112, 1, '    public static int canCompleteCircuit(int[] gas, int[] cost) {
        int len = gas.length;
        int[] diff = new int[len];
        int to = 0;
        for (int i = 0; i < len; i++) {
            diff[i] += (gas[i] - cost[i]);
            to += diff[i];
        }
        if (to < 0) {
            return -1;
        }
        int index = 0;
        to = 0;
        for (int i = 0; i < len; i++) {
            to += diff[i];
            if (to < 0) {
                index = i + 1;
                to = 0;
            }
        }
        return index;
    }', 235);
