INSERT INTO schema_problem.solution_code VALUES (202, 122, 1, '
    public static int findMissingNumber(int arr[], int n) {
        int sum = n * (n + 1) / 2;
        int actualSum = 0;
        for (int i = 0; i < n - 1; i++) {
            actualSum += arr[i];
        }
        return sum - actualSum;
    }', NULL);
