INSERT INTO schema_problem.solution_code VALUES (203, 123, 2, '
    char* reverseString(char s[]) {
        int left = 0, right = strlen(s) - 1;
        while (left < right) {
            char temp = s[left];
            s[left] = s[right];
            s[right] = temp;
            left++;
            right--;
        }
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (209, 129, 1, '
public static String minWindow(String s, String t) {
    if (t.length() > s.length()) return "";
    Map<Character, Integer> map = new HashMap<>();
    for (char c : t.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    int left = 0, right = 0, minStart = 0, minLen = Integer.MAX_VALUE, count = t.length();
    while (right < s.length()) {
        if (map.containsKey(s.charAt(right))) {
            if (map.get(s.charAt(right)) > 0) count--;
            map.put(s.charAt(right), map.get(s.charAt(right)) - 1);
        }
        right++;
        while (count == 0) {
            if (right - left < minLen) {
                minLen = right - left;
                minStart = left;
            }
            if (map.containsKey(s.charAt(left))) {
                map.put(s.charAt(left), map.get(s.charAt(left)) + 1);
                if (map.get(s.charAt(left)) > 0) count++;
            }
            left++;
        }
    }
    return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (214, 134, 1, '
    public static int myAtoi(String s) {
        s = s.trim(); 
        int sign = 1, i = 0;
        long res = 0; 

        if (s.length() == 0) return 0;


        if (s.charAt(0) == ''-'') { sign = -1; i++; }
        else if (s.charAt(0) == ''+'') { i++; }

        while (i < s.length()) {
            char ch = s.charAt(i);
            if (ch < ''0'' || ch > ''9'') break;

            res = res * 10 + (ch - ''0'');
            if (sign * res > Integer.MAX_VALUE) return Integer.MAX_VALUE;
            if (sign * res < Integer.MIN_VALUE) return Integer.MIN_VALUE;

            i++;
        }
        return (int) (sign * res);
    }', NULL);
