           }
           else{
               sb.append(count).append(p.charAt(i-1));
               count=1;
           }
        }   
        sb.append(count).append(p.charAt(q-1));
        return sb.toString();
       }', NULL);
INSERT INTO schema_problem.solution_code VALUES (221, 142, 1, '
    public static int findMinFibonacciNumbers(int k) {
        if (k<=1) {
            return k;
        }
        int a = 1, b = 1, c = 2;
        while (c<=k) {
            a = b;
            b = c;
            c = a+b;
        }
        return 1 + findMinFibonacciNumbers(k-b);
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (221, 142, 2, '
    int findMinFibonacciNumbers(int k) {
        long long a = 1, b = 1, temp, count = 0;

        while (b <= k) {
            temp = a + b;
            a = b;
            b = temp;
        }

        while (k > 0) {
            if (a <= k) {
                k -= a;
                count++;
            }

            temp = b - a;
            b = a;
            a = temp;
        }

        return count;
    }', NULL);
