INSERT INTO schema_problem.solution_code VALUES (211, 131, 1, '
public static String longestPalindrome(String s) {
    int start = 0, maxLen = 0;
    for (int i = 0; i < s.length(); i++) {
        int len1 = expandAroundCenter(s, i, i);
        int len2 = expandAroundCenter(s, i, i + 1);
        int len = Math.max(len1, len2);
        if (len > maxLen) {
            start = i - (len - 1) / 2;
            maxLen = len;
        }
    }
    return s.substring(start, start + maxLen);
}
private static int expandAroundCenter(String s, int left, int right) {
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
        left--;
        right++;
    }
    return right - left - 1;
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (211, 131, 2, '
char* longestPalindrome(char* s) {
    int start = 0, maxLen = 0, len = strlen(s);
    for (int i = 0; i < len; i++) {
        int len1 = expandAroundCenter(s, i, i);
        int len2 = expandAroundCenter(s, i, i + 1);
        int palLen = (len1 > len2) ? len1 : len2;
        if (palLen > maxLen) {
            start = i - (palLen - 1) / 2;
            maxLen = palLen;
        }
    }
    char* result = (char*)malloc((maxLen + 1) * sizeof(char));
    strncpy(result, s + start, maxLen);
    result[maxLen] = ''\0'';
    return result;
}
int expandAroundCenter(char* s, int left, int right) {
    while (left >= 0 && right < strlen(s) && s[left] == s[right]) {
        left--;
        right++;
    }
    return right - left - 1;
}', NULL);
INSERT INTO schema_problem.solution_code VALUES (216, 136, 1, '
    public static boolean isNumber(String s) {
        boolean isdot = false, ise = false, nums = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) nums = true;
            else if (c == ''+'' || c == ''-'') {
                if (i > 0 && s.charAt(i - 1) != ''e'' && s.charAt(i - 1) != ''E'') return false;
            } 
            else if (c == ''e'' || c == ''E'') {
                if (ise || !nums) return false;
                ise = true;
                nums = false;
            } 
            else if (c == ''.'') {
                if (isdot || ise) return false;
                isdot = true;
            } 
            else return false;
        }
        return nums;
    }', NULL);
