INSERT INTO schema_problem.solution_code VALUES (212, 132, 1, '
    public static int romanToInt(String s) {
        int res = 0;
        Map<Character, Integer> roman = new HashMap<>();
        roman.put(''I'', 1);
        roman.put(''V'', 5);
        roman.put(''X'', 10);
        roman.put(''L'', 50);
        roman.put(''C'', 100);
        roman.put(''D'', 500);
        roman.put(''M'', 1000);

        for (int i = 0; i < s.length() - 1; i++) {
            if (roman.get(s.charAt(i)) < roman.get(s.charAt(i + 1))) {
                res -= roman.get(s.charAt(i));
            } else {
                res += roman.get(s.charAt(i));
            }
        }

        return res + roman.get(s.charAt(s.length() - 1));        
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (190, 112, 1, '    public static int canCompleteCircuit(int[] gas, int[] cost) {
        int len = gas.length;
        int[] diff = new int[len];
        int to = 0;
        for (int i = 0; i < len; i++) {
            diff[i] += (gas[i] - cost[i]);
            to += diff[i];
        }
        if (to < 0) {
            return -1;
        }
        int index = 0;
        to = 0;
        for (int i = 0; i < len; i++) {
            to += diff[i];
            if (to < 0) {
                index = i + 1;
                to = 0;
            }
        }
        return index;
    }', 215);
INSERT INTO schema_problem.solution_code VALUES (212, 132, 2, '
    int romanToInt(char* s) {
        int res=0;
        int pre=0;
        char roman[7]={''I'', ''V'', ''X'', ''L'', ''C'', ''D'', ''M''};

        int val[7]={1,5,10,50,100,500,1000};
        for (int i=strlen(s)-1;i>=0;i--){
            for (int j=0;j<7;j++){
                if (s[i]==roman[j]){
                    if (val[j]<pre){
                        res-=pre;
                        pre-=val[j];
                        res+=pre;
                    }else{
                        res+=val[j];
                        pre=val[j];

                    }
                }

            }
        }
        return res;

    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (213, 133, 1, '
        public static String convert(String s, int numRows) {
       if (numRows == 1 || numRows >= s.length()) {
            return s;
        }

        int idx = 0, d = 1;
        List<Character>[] rows = new ArrayList[numRows];
        for (int i = 0; i < numRows; i++) {
            rows[i] = new ArrayList<>();
        }

        for (char c : s.toCharArray()) {
            rows[idx].add(c);
            if (idx == 0) {
                d = 1;
            } else if (idx == numRows - 1) {
                d = -1;
            }
            idx += d;
        }

        StringBuilder result = new StringBuilder();
        for (List<Character> row : rows) {
            for (char c : row) {
                result.append(c);
            }
        }

        return result.toString();        
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (213, 133, 2, '
