INSERT INTO schema_problem.solution_code VALUES (249, 170, 1, '
    public static int countFibonacciDivisible(int n, int k) {
        int a = 0, b = 1, count = 0;
        for (int i = 2; a < n; i++) {
            int temp = a + b;
            a = b;
            b = temp;
            if (a >= n)
                break;
            if (a % k == 0)
                count++;
        }
        return count;
    }', NULL);
