INSERT INTO schema_problem.solution_code VALUES (285, 206, 1, '
    public static int mostFrequent(int[] arr) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : arr) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        int maxCount = 0, mostFreqNum = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            if (entry.getValue() > maxCount || (entry.getValue() == maxCount && entry.getKey() < mostFreqNum)) {
                maxCount = entry.getValue();
                mostFreqNum = entry.getKey();
            }
        }
        return mostFreqNum;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (285, 206, 2, '
    int mostFrequent(int arr[], int size) {
        int maxCount = 0, mostFreqNum = arr[0];

        for (int i = 0; i < size; i++) {
            int count = 1;
            for (int j = i + 1; j < size; j++) {
                if (arr[i] == arr[j]) count++;
            }

            if (count > maxCount || (count == maxCount && arr[i] < mostFreqNum)) {
                maxCount = count;
                mostFreqNum = arr[i];
            }
        }
        return mostFreqNum;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (286, 207, 1, '
    public static int[] removeDuplicates(int[] arr) {
        Set<Integer> set = new LinkedHashSet<>();
        for (int num : arr) {
            set.add(num);
        }

        int[] uniqueArray = new int[set.size()];
        int index = 0;
        for (int num : set) {
            uniqueArray[index++] = num;
        }
        return uniqueArray;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (286, 207, 2, '
    int* removeDuplicates(int arr[], int size) {
        int unique[size], index = 0;

        for (int i = 0; i < size; i++) {
            int found = 0;
            for (int j = 0; j < index; j++) {
                if (arr[i] == unique[j]) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                unique[index++] = arr[i];
            }
        }
        return arr;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (287, 208, 1, '
    public static int[] mergeAndSort(int[] arr1, int[] arr2) {
        int[] mergedArray = new int[arr1.length + arr2.length];
        System.arraycopy(arr1, 0, mergedArray, 0, arr1.length);
        System.arraycopy(arr2, 0, mergedArray, arr1.length, arr2.length);

        Arrays.sort(mergedArray);
        return mergedArray;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (287, 208, 2, '
    int* mergeAndSort(int arr1[], int size1, int arr2[], int size2) {
        int size = size1 + size2;
        int merged[size];

        for (int i = 0; i < size1; i++) merged[i] = arr1[i];
        for (int i = 0; i < size2; i++) merged[size1 + i] = arr2[i];

        for (int i = 0; i < size - 1; i++) {
            for (int j = i + 1; j < size; j++) {
                if (merged[i] > merged[j]) {
                    int temp = merged[i];
                    merged[i] = merged[j];
                    merged[j] = temp;
                }
            }
        }

        return merged;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (288, 209, 1, '
    public static int maxSubarraySum(int[] arr) {
        int maxSum = arr[0], currentSum = arr[0];
        for (int i = 1; i < arr.length; i++) {
            currentSum = Math.max(arr[i], currentSum + arr[i]);
            maxSum = Math.max(maxSum, currentSum);
        }
        return maxSum;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (288, 209, 2, '
    int maxSubarraySum(int arr[], int size) {
        int maxSum = arr[0], currentSum = arr[0];

        for (int i = 1; i < size; i++) {
            if (currentSum + arr[i] > arr[i]) {
                currentSum += arr[i];
            } else {
                currentSum = arr[i];
            }
            if (currentSum > maxSum) {
                maxSum = currentSum;
            }
        }
        return maxSum;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (289, 210, 1, '
    public static int[] reverse(int[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
        return arr;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (289, 210, 2, '
    int* reverse(int arr[], int size) {
        int left = 0, right = size - 1, temp;
        while (left < right) {
            temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
        return arr;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (290, 211, 2, '
    int isFibonacciArray(int arr[], int size) {
        if (size < 3) return 0;
        for (int i = 2; i < size; i++) {
            if (arr[i] != arr[i - 1] + arr[i - 2]) {
                return 0;
            }
        }
        return 1;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (291, 212, 1, '
    public static int countOddFrequency(int[] arr) {
        HashMap<Integer, Integer> freqMap = new HashMap<>();
        for (int num : arr) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }
        int count = 0;
        for (int freq : freqMap.values()) {
            if (freq % 2 != 0) count++;
        }
        return count;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (291, 212, 2, '
    int countOddFrequency(int arr[], int size) {
        int count = 0;
        for (int i = 0; i < size; i++) {
            int freq = 0;
            for (int j = 0; j < size; j++) {
                if (arr[i] == arr[j]) freq++;
            }
            if (freq % 2 != 0) {
                count++;
                for (int k = i + 1; k < size; k++) {
                    if (arr[k] == arr[i]) arr[k] = -1;
                }
            }
        }
        return count;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (292, 213, 1, '
    public static int firstUnique(int[] arr) {
        LinkedHashMap<Integer, Integer> map = new LinkedHashMap<>();
        for (int num : arr) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == 1) return entry.getKey();
        }
        return -1;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (292, 213, 2, '
    int firstUnique(int arr[], int size) {
        for (int i = 0; i < size; i++) {
            int count = 0;
            for (int j = 0; j < size; j++) {
                if (arr[i] == arr[j]) count++;
            }
            if (count == 1) return arr[i];
        }
        return -1;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (293, 214, 1, '
    public static int[] rearrange(int[] arr) {
        List<Integer> evens = new ArrayList<>();
        List<Integer> odds = new ArrayList<>();

        for (int num : arr) {
            if (num % 2 == 0) evens.add(num);
            else odds.add(num);
        }
        evens.addAll(odds);
        return evens.stream().mapToInt(Integer::intValue).toArray();
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (293, 214, 2, '
    int* rearrange(int arr[], int size) {
        int temp[size], index = 0;

        for (int i = 0; i < size; i++) {
            if (arr[i] % 2 == 0) temp[index++] = arr[i];
        }
        for (int i = 0; i < size; i++) {
            if (arr[i] % 2 != 0) temp[index++] = arr[i];
        }
        for (int i = 0; i < size; i++) {
            arr[i] = temp[i];
        }
        return arr;
    }', NULL);
