INSERT INTO schema_problem.solution_code VALUES (312, 233, 1, '
    public static int findMostFrequentElement(List<Integer> list) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : list) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        int maxFreq = 0, result = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            if (entry.getValue() > maxFreq || (entry.getValue() == maxFreq && entry.getKey() < result)) {
                maxFreq = entry.getValue();
                result = entry.getKey();
            }
        }
        return result;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (313, 234, 1, '
    public static int[] findClosestPair(List<Integer> list, int n) {
        Collections.sort(list);
        int left = 0, right = list.size() - 1;
        int closestSum = Integer.MAX_VALUE, num1 = 0, num2 = 0;

        while (left < right) {
            int sum = list.get(left) + list.get(right);
            if (Math.abs(sum - n) < Math.abs(closestSum - n)) {
                closestSum = sum;
                num1 = list.get(left);
                num2 = list.get(right);
            }

            if (sum < n) left++;
            else right--;
        }
        return new int[]{num1, num2};
    }', NULL);
