INSERT INTO schema_problem.solution_code VALUES (315, 236, 1, '
    public static int findSmallestLargerThanPrevious(List<Integer> list) {
        int minValue = Integer.MAX_VALUE;
        boolean found = false;

        for (int i = 1; i < list.size(); i++) {
            if (list.get(i) > list.get(i - 1) && list.get(i) < minValue) {
                minValue = list.get(i);
                found = true;
            }
        }
        return found ? minValue : -1;
    }', NULL);
