INSERT INTO schema_problem.solution_code VALUES (322, 243, 1, '
    public static Set findLargestCommonSubset(List<Integer> list1, List<Integer> list2) {
        Map<Integer, Integer> freqMap1 = new HashMap<>();
        Map<Integer, Integer> freqMap2 = new HashMap<>();

        for (int num : list1) {
            freqMap1.put(num, freqMap1.getOrDefault(num, 0) + 1);
        }
        for (int num : list2) {
            freqMap2.put(num, freqMap2.getOrDefault(num, 0) + 1);
        }

        Set<Integer> commonSubset = new HashSet<>();
        for (int num : freqMap1.keySet()) {
            if (freqMap2.containsKey(num) && freqMap1.get(num).equals(freqMap2.get(num))) {
                commonSubset.add(num);
            }
        }
        return commonSubset;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (323, 244, 1, '
    public static int findSmallestMissingPositive(List<Integer> list) {
        Set<Integer> numberSet = new HashSet<>();
        for (int num : list) {
            if (num > 0) {
                numberSet.add(num);
            }
        }

        int smallestMissing = 1;
        while (numberSet.contains(smallestMissing)) {
            smallestMissing++;
