INSERT INTO schema_problem.solution_code VALUES (332, 253, 1, '
    public static String mostFrequentWord(String text) {
        Map<String, Integer> wordCount = new HashMap<>();
        String[] words = text.split("\s+");

        for (String word : words) {
            wordCount.put(word, wordCount.getOrDefault(word, 0) + 1);
        }

        String maxWord = null;
        int maxCount = 0;

        for (Map.Entry<String, Integer> entry : wordCount.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxWord = entry.getKey();
                maxCount = entry.getValue();
            }
        }

        return maxWord;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (333, 254, 1, '
    public static List groupAnagrams(String[] words) {
        Map<String, List<String>> map = new HashMap<>();

        for (String word : words) {
            char[] charArray = word.toCharArray();
            Arrays.sort(charArray);
            String sortedWord = new String(charArray);

            map.putIfAbsent(sortedWord, new ArrayList<>());
            map.get(sortedWord).add(word);
        }

        return new ArrayList<>(map.values());
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (334, 255, 1, '
    public static int mostFrequentNumber(int[] nums) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int num : nums) {
            frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
        }

        int maxFreq = 0, minNum = Integer.MAX_VALUE;
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            if (entry.getValue() > maxFreq || (entry.getValue() == maxFreq && entry.getKey() < minNum)) {
                maxFreq = entry.getValue();
                minNum = entry.getKey();
            }
        }

        return minNum;
    }', NULL);
