INSERT INTO schema_problem.solution_code VALUES (336, 257, 1, '
    public static int maxDistance(int[] nums) {
        Map<Integer, Integer> firstIndexMap = new HashMap<>();
        int maxDist = 0;

        for (int i = 0; i < nums.length; i++) {
            if (!firstIndexMap.containsKey(nums[i])) {
                firstIndexMap.put(nums[i], i);
            } else {
                maxDist = Math.max(maxDist, i - firstIndexMap.get(nums[i]));
            }
        }

        return maxDist;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (337, 258, 1, '
    public static String reverseString(String str) {
        Stack<Character> stack = new Stack<>();
        for (char c : str.toCharArray()) {
            stack.push(c);
        }

        StringBuilder reversed = new StringBuilder();
        while (!stack.isEmpty()) {
            reversed.append(stack.pop());
        }
        return reversed.toString();
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (338, 259, 1, '
    public static boolean isValidParentheses(String str) {
        Stack<Character> stack = new Stack<>();
        Map<Character, Character> pairs = Map.of('')'', ''('', ''}'', ''{'', '']'', ''['');

        for (char c : str.toCharArray()) {
            if (pairs.containsValue(c)) {
                stack.push(c);
            } else if (pairs.containsKey(c)) {
                if (stack.isEmpty() || stack.pop() != pairs.get(c)) {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (340, 261, 1, '
    public static int largestRectangleArea(int[] heights) {
        Stack<Integer> stack = new Stack<>();
        int maxArea = 0, i = 0;
        while (i < heights.length) {
            if (stack.isEmpty() || heights[i] >= heights[stack.peek()]) {
                stack.push(i++);
            } else {
                int h = heights[stack.pop()];
                int w = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, h * w);
            }
        }
        while (!stack.isEmpty()) {
            int h = heights[stack.pop()];
            int w = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, h * w);
        }
        return maxArea;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (341, 262, 1, '
    public static int[] findNGE(int[] arr) {
        int[] result = new int[arr.length];
        Stack<Integer> stack = new Stack<>();

        for (int i = arr.length - 1; i >= 0; i--) {
            while (!stack.isEmpty() && stack.peek() <= arr[i]) {
                stack.pop();
            }
            result[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(arr[i]);
        }
        return result;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (342, 263, 1, '
    public static boolean isPalindrome(String str) {
        Queue<Character> queue = new LinkedList<>();
        Stack<Character> stack = new Stack<>();

        for (char ch : str.toCharArray()) {
            queue.offer(ch);
            stack.push(ch);
        }

        while (!queue.isEmpty()) {
            if (!queue.poll().equals(stack.pop())) {
                return false;
            }
        }
        return true;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (343, 264, 1, '
    public static List generateBinary(int n) {
        List<String> result = new ArrayList<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer("1");

        for (int i = 0; i < n; i++) {
            String binary = queue.poll();
            result.add(binary);
            queue.offer(binary + "0");
            queue.offer(binary + "1");
        }
        return result;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (344, 265, 1, '
    public static int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n - k + 1];
        Deque<Integer> deque = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            while (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {
                deque.pollFirst();
            }
            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);
            if (i >= k - 1) {
                result[i - k + 1] = nums[deque.peekFirst()];
            }
        }
        return result;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (345, 266, 1, '
    public static int minCheckoutTime(int[] customers, int K) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < K; i++) pq.offer(0);

        for (int c : customers) {
            pq.offer(pq.poll() + c);
        }

        int maxTime = 0;
        while (!pq.isEmpty()) {
            maxTime = Math.max(maxTime, pq.poll());
        }
        return maxTime;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (346, 267, 1, '
    public static int roundRobin(int[] processes, int quantum) {
        Queue<Integer> queue = new LinkedList<>();
        for (int p : processes) queue.offer(p);

        int time = 0;
        while (!queue.isEmpty()) {
            int p = queue.poll();
            if (p > quantum) {
                time += quantum;
                queue.offer(p - quantum);
            } else {
                time += p;
            }
        }
        return time;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (347, 268, 1, '
    public static boolean isPowerOfFour(int n) {
        while (n >= 4) {
            if (n % 4 != 0) {
                return false;
            } else {
                n = n / 4;
            }

        }
        return n == 1;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (348, 269, 1, '
    public static int countDigitOne(int n) {
        if (n <= 0)
            return 0;
        int q = n, x = 1, ans = 0;
        do {
            int digit = q % 10;
            q /= 10;
            ans += q * x;
            if (digit == 1)
                ans += n % x + 1;
            if (digit > 1)
                ans += x;
            x *= 10;
        } while (q > 0);
        return ans;
    }', NULL);
INSERT INTO schema_problem.solution_code VALUES (349, 270, 1, '
    public static int calculate(String s) {
        int number = 0;
        int signValue = 1;
        int result = 0;
        Stack<Integer> operationsStack = new Stack<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                number = number * 10 + (c - ''0'');
            } else if (c == ''+'' || c == ''-'') {
                result += number * signValue;
                signValue = (c == ''-'') ? -1 : 1;
                number = 0;
            } else if (c == ''('') {
                operationsStack.push(result);
                operationsStack.push(signValue);
                result = 0;
                signValue = 1;
            } else if (c == '')'') {
                result += signValue * number;
                result *= operationsStack.pop();
                result += operationsStack.pop();
                number = 0;
            }
        }

        return result + number * signValue;
    }', NULL);
